<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
class PostDeliveryReturnService {
 private const OPEN=['submitted','seller_approved','rider_collected_return','returned_to_seller','seller_received_return'];
 public function paymentBreakdown(string $orderId): array { $rows=DB::table('payment_transactions')->where('order_id',$orderId)->where('payment_status','paid')->get(); $paid=round((float)$rows->sum('amount'),2); return ['payment'=>$paid,'service_fee'=>0,'total'=>$paid]; }
 public function eligible(object $o): array { if(($o->fulfillment_type??'')==='Pickup'&&($o->status??'')==='Pickup')return[true,null]; if(($o->fulfillment_type??'')==='Delivery'&&($o->status??'')==='Out for Delivery'&&!empty($o->rider_arrived_at))return[true,null]; return[false,'You can report a delivery issue only while the rider is at your location, before delivery is completed.']; }
 public function submit(object $order,string $customerId,array $data,array $evidence):object { return DB::transaction(function()use($order,$customerId,$data,$evidence){$o=DB::table('orders')->where('id',$order->id)->lockForUpdate()->first();[$ok,$msg]=$this->eligible($o);if(!$ok)throw new \DomainException($msg);if(DB::table('post_delivery_return_cases')->where('order_id',$o->id)->whereIn('status',self::OPEN)->lockForUpdate()->exists())throw new \DomainException('A return request is already active for this order.');$amount=$this->paymentBreakdown($o->id)['total'];if($amount<=0)throw new \DomainException('No confirmed customer payment is available for refund.');$id=DB::table('post_delivery_return_cases')->insertGetId(['case_number'=>'RET-TMP-'.bin2hex(random_bytes(8)),'order_id'=>$o->id,'shop_id'=>$o->shop_id,'customer_user_id'=>$customerId,'seller_user_id'=>$o->shop_id?DB::table('shops')->where('id',$o->shop_id)->value('seller_id'):null,'reason'=>$data['reason'],'description'=>$data['description'],'status'=>'submitted','customer_payment_amount'=>$amount,'service_fee_amount'=>0,'requested_amount'=>$amount,'refund_gcash_name'=>$data['refund_gcash_name'],'refund_gcash_number'=>$data['refund_gcash_number'],'submitted_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('post_delivery_return_cases')->where('id',$id)->update(['case_number'=>'RET-'.now()->format('Ymd').'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT)]);foreach($evidence as $e)DB::table('post_delivery_return_evidence')->insert($e+['return_case_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);DB::table('order_tracking')->insert(['order_id'=>$o->id,'status'=>'Return Requested','notes'=>'Customer submitted a return request during inspection.','created_at'=>now()]);return DB::table('post_delivery_return_cases')->where('id',$id)->first();}); }
 public function sellerDecide(int $id,string $seller,string $decision,?string $note):void { DB::transaction(function()use($id,$seller,$decision,$note){$c=DB::table('post_delivery_return_cases')->where('id',$id)->lockForUpdate()->first();if(!$c||(string)$c->seller_user_id!==$seller||$c->status!=='submitted')throw new \DomainException('This request is not awaiting your decision.');if($decision==='rejected'&&strlen(trim((string)$note))<10)throw new \DomainException('A rejection reason of at least 10 characters is required.');$status=$decision==='approved'?'seller_approved':'seller_rejected';DB::table('post_delivery_return_cases')->where('id',$id)->update(['status'=>$status,'seller_decision'=>$decision,'seller_decision_note'=>trim((string)$note)?:null,'seller_response'=>trim((string)$note)?:null,'seller_decided_by_user_id'=>$seller,'seller_decided_at'=>now(),'approved_amount'=>$decision==='approved'?$c->requested_amount:null,'updated_at'=>now()]);DB::table('order_tracking')->insert(['order_id'=>$c->order_id,'status'=>$status==='seller_approved'?'Return Approved':'Return Rejected','notes'=>$note?:'Seller decision saved.','created_at'=>now()]);}); }
 public function riderCollect(int $id,string $orderId,string $proof):void {$c=DB::table('post_delivery_return_cases')->where('id',$id)->where('order_id',$orderId)->where('status','seller_approved')->first();if(!$c)throw new \DomainException('Return is not ready for collection.');DB::table('post_delivery_return_cases')->where('id',$id)->update(['status'=>'rider_collected_return','rider_collected_return_at'=>now(),'rider_return_proof_path'=>$proof,'updated_at'=>now()]);}
 public function riderReturned(int $id,string $orderId):void {$c=DB::table('post_delivery_return_cases')->where('id',$id)->where('order_id',$orderId)->where('status','rider_collected_return')->first();if(!$c)throw new \DomainException('Return is not ready to be marked returned.');DB::table('post_delivery_return_cases')->where('id',$id)->update(['status'=>'returned_to_seller','rider_returned_to_seller_at'=>now(),'updated_at'=>now()]);}
 public function sellerReceive(int $id,string $seller):void {$c=DB::table('post_delivery_return_cases')->where('id',$id)->where('status','returned_to_seller')->first();if(!$c||(string)$c->seller_user_id!==$seller)throw new \DomainException('Return is not ready for receipt confirmation.');DB::table('post_delivery_return_cases')->where('id',$id)->update(['status'=>'seller_received_return','seller_received_return_at'=>now(),'seller_received_return_by_user_id'=>$seller,'updated_at'=>now()]);}
 public function completeRefund(int $id,string $admin,string $ref,string $path,string $hash):void {DB::transaction(function()use($id,$admin,$ref,$path,$hash){$c=DB::table('post_delivery_return_cases')->where('id',$id)->lockForUpdate()->first();$o=$c?DB::table('orders')->where('id',$c->order_id)->first():null;if(!$c||!$o||(($o->fulfillment_type??'')==='Delivery'&&$c->status!=='seller_received_return')||(($o->fulfillment_type??'')==='Pickup'&&$c->status!=='seller_approved'))throw new \DomainException('Refund is not ready for processing.');if(DB::table('post_delivery_return_cases')->where('id','<>',$id)->where('refund_reference',$ref)->exists())throw new \DomainException('Refund reference is already used.');DB::table('post_delivery_return_cases')->where('id',$id)->update(['status'=>'refunded','refund_reference'=>$ref,'refund_receipt_path'=>$path,'refund_receipt_hash'=>$hash,'refunded_at'=>now(),'refunded_by_user_id'=>$admin,'updated_at'=>now()]);});}
}
